# AtomicAndPhysicalConstants/src/CODATA2006.jl
# Constants pulled from the NIST table of
# the 2006 CODATA release
# Generated by update/update_constants.jl; masses are NIST's
# "energy equivalent in MeV" values with the decimal point moved to eV.



#####################################################################
# Physical constants
#####################################################################


"""
    CODATA2006 :: CODATA_release

Fundamental constants from the 2006 CODATA release.

See [NIST CODATA](https://physics.nist.gov/cuu/Constants/) for the
primary source values.
"""
const CODATA2006 = CODATA_release(

#######################################
# constants with dimension [mass]
#######################################


M_ELECTRON = 510998.91,
# Electron Mass [eV]/c^2
M_PROTON = 9.38272013e8,
# Proton Mass [eV]/c^2
M_NEUTRON = 9.39565346e8,
# Neutron Mass [eV]/c^2
M_MUON = 1.056583668e8,
# Muon Mass [eV]/c^2
M_HELION = 2.808391383e9,
# Helion Mass He3 nucleus [eV]/c^2
M_DEUTERON = 1.875612793e9,
# Deuteron Mass [eV]/c^2
M_TRITON = 2.808920906e9,
# Triton Mass [eV]/c^2

# not tabulated by CODATA; fit values from the 2006 edition of the
# PDG Review of Particle Physics
M_PION_0 = 1.349766175723028e8,
# uncharged pion mass [eV]/c^2
M_PION_CHARGED = 1.395701807882995e8,
# charged pion mass [eV]/c^2


#######################################
# constants with dimension [magnetic moment]
#######################################


MU_DEUTERON_SI = 4.33073465e-27,
# deuteron magnetic moment in [J/T]
MU_ELECTRON_SI = -9.28476377e-24,
# electron magnetic moment in [J/T]
MU_HELION_SI = NaN,
# not tabulated in the 2006 release
# helion magnetic moment in [J/T]
MU_MUON_SI = -4.49044786e-26,
# muon magnetic moment in [J/T]
MU_NEUTRON_SI = -9.6623641e-27,
# neutron magnetic moment in [J/T]
MU_PROTON_SI = 1.410606662e-26,
# proton magnetic moment in [J/T]
MU_TRITON_SI = 1.504609361e-26,
# triton magnetic moment in [J/T]


#######################################
# dimensionless constants
#######################################


AVOGADRO = 6.02214179e23,
# Avogadro's constant: Number / mole (exact)
FINE_STRUCTURE = 0.0072973525376,
# fine structure constant

ANOMALY_ELECTRON = 0.00115965218111,
# electron magnetic moment anomaly
ANOMALY_MUON = 0.00116592069,
# muon magnetic moment anomaly

G_DEUTERON_NUCLEAR_MAGNETON = 0.8574382308,
# deuteron g factor
G_ELECTRON = -2.0023193043622,
# electron g factor
G_HELION_NUCLEAR_MAGNETON = NaN,
# not tabulated in the 2006 release
# helion g factor
G_MUON = -2.0023318414,
# muon g factor
G_NEUTRON_NUCLEAR_MAGNETON = -3.82608545,
# neutron g factor
G_PROTON = 5.585694713,
# proton g factor
G_TRITON_NUCLEAR_MAGNETON = 5.957924896,
# triton g factor


#######################################
# constants with miscellaneous dimension
#######################################


E_CHARGE = 1.602176487e-19,
# elementary charge [C]
R_ELECTRON = 2.8179402894e-15,
# classical electron radius [m]
R_PROTON = 1.534698249950342e-18,
# classical proton radius [m], R_ELECTRON * M_ELECTRON / M_PROTON
C_LIGHT = 2.99792458e8,
# speed of light [m/s]
H_PLANCK = 4.13566733e-15,
# Planck's constant [eV*s]
H_BAR = 6.58211899e-16,
# h_planck/twopi [eV*s]

K_BOLTZMANN = 8.617343e-5,
#k_B in eV/K

EPS_0 = 5.526349868109373e7,
# Permittivity of free space in [1/(eV*m)]
MU_0 = 2.0133543525254011e-25,
# Vacuum permeability in [eV*s^2/m]


G_PER_AMU = 1.660538782e-24,
# grams per standard atomic mass unit (dalton)

EV_PER_AMU = 9.31494028e8,
# eV/c^2 per standard atomic mass unit (dalton)

J_PER_EV = 1.602176487e-19,
# Joules per eV

EV_PER_J = 6.24150965e18,
# eV per Joule

G_PER_EV = 1.782661758e-33,
# grams per eV/c^2

RELEASE_YEAR = 2006


)

